@startuml

class User {
  + Name : string
  + Email : string
}

class Student extends User {
  + Name : string
  + Email : string
}

class Tutor extends User {
  + Name : string
  + Email : string
  + BankAccount : string
}

class Subject {
  + Name : string
}

class TutoringOffer {
  + ExpertiseLevel : string
  + HourlyPrice : float
}

class Availability {
  + DayOfWeek : string
  + StartTime : time
  + EndTime : time
}

class TutoringRequest {
  + Level : string
  + SuggestedDateTime : datetime
}

class TutoringSession {
  + ActualDateTime : datetime
  + Status : string
  + PaymentMethod : string
  + IsCancelled : boolean
  + CancellationTime : datetime
}

Student "0..*" -- "0..*" Tutor : requests
Tutor "1" -- "0..*" TutoringOffer : offers
TutoringOffer "0..*" -- "1" Subject
Tutor "1" -- "0..*" Availability
Tutor "1" -- "0..*" TutoringOffer
Student "1" -- "0..*" TutoringSession
Tutor "1" -- "0..*" TutoringSession
TutoringRequest "1" -- "1" Tutor
TutoringRequest "1" -- "1" Student
TutoringRequest "1" -- "1" TutoringSession
TutoringSession "0..*" -- "1" TutoringOffer

@enduml

